// ============================================================
// MOTOR DE INFERENCIA — SISTEMA EXPERTO AGRÍCOLA
// Nodo Code de WF1 (Fase 4.4).
// Última actualización: 19/10/2026 (sesión 17) — incluye 13.3.2, 13.3.3, 13.4.2, 16.35, 16.36, 16.37,
// 13.7.2 (recheck de riego y freno con rearme) y el contrato v1, paso 2 (cierra 16.52)
// ============================================================
// 1. OBTENER DATOS DE NODOS ANTERIORES
// La lectura YA VALIDADA y normalizada por `Validar Contrato` (contrato v1, paso 2).
// El Motor nunca lee el cuerpo crudo del Webhook: cada medición llega como número
// dentro del rango físico del sensor, o como null. Cierra 16.52 (`"" < 60` era sequía).
const sensor = $('Validar Contrato').first().json.lectura;
let fotoBase64Raw = sensor.foto_base64 || null;
//n8n envuelve strings grandes en {value: "..."}
//Para que viaje limpio a todos los consumidores
let fotoBase64 = (fotoBase64Raw && typeof fotoBase64Raw === 'object' && 'value' in fotoBase64Raw)
  ? fotoBase64Raw.value
  : fotoBase64Raw;
// limpiar espacios/saltos de línea que puedan colarse (ej: archivo de test con \r\n final)
if (fotoBase64) fotoBase64 = fotoBase64.trim();
// Una foto real en base64 pesa decenas de miles de caracteres.
// Menos de ~1000 es un archivo truncado, vacío o corrupto: no vale la llamada a Gemini.
const fotoPlausible = !!fotoBase64 && fotoBase64.length > 1000;

// Datos del cultivo activo (de vista_cultivos_activos)
// --- 16.35: NORMALIZACIÓN EN EL BORDE ---
// Los booleanos que llegan de la base se fuerzan a tipo boolean UNA sola vez, acá,
// en el productor, en vez de defenderse en cada consumidor. `tiene_actuador_riego`
// es anulable en `dispositivo` y `Dispara WF5` lo lee con typeValidation: strict.
// Cuarta aparición del mismo patrón (16.12, v23, Bug 4 de 13.3.3): la revisión caso
// por caso ya demostró que no alcanza.
const cultivoRaw = $('Resolver Cultivo').first().json;
const cultivo = { ...cultivoRaw, tiene_actuador_riego: !!cultivoRaw.tiene_actuador_riego };
// Conocimiento experto: UNA fila plana con todos los umbrales
const reglas = $('Conocimiento Experto').first().json;

// --- Modo mantenimiento (13.12). Se calcula ANTES que nada para que los dos caminos
//     de salida del nodo devuelvan el mismo contrato de campos (ver 13.3.3) ---
const enMantenimiento = !!(cultivo.mantenimiento_hasta && new Date(cultivo.mantenimiento_hasta) > new Date());

// ============================================================
// 16.37 — VALIDACIÓN POSITIVA DEL CONOCIMIENTO EXPERTO
// ------------------------------------------------------------
// `vista_conocimiento_experto` hace INNER JOIN contra `parametro_etapa`: una etapa sin
// umbrales cargados NO devuelve nulos, no devuelve NADA. Y como `Conocimiento Experto`
// tiene `alwaysOutputData: true` (defensa contra el Bug 3, el nodo que emite cero ítems
// y corta la rama en silencio), ante cero filas emite un ítem vacío `{}` que viaja
// aguas abajo como si fuera información.
//
// Sin esta guarda: `20 < undefined` y `20 > undefined` dan los DOS `false` —en JS toda
// relacional contra undefined es falsa en ambos sentidos—, `estadoGlobal` se queda en
// 'OK', y el cultivo se reporta SANO INDEFINIDAMENTE con todas las ejecuciones en verde.
// Es la categoría peor definida por el propio plan: no una caída, una fila que miente.
//
// Se chequean humedad y pH y no los ideales de NPK a propósito: el bucle de NPK ya tiene
// su propia guarda explícita (`if (check.ideal === null) continue`), así que su ausencia
// es un skip declarado y no un accidente de coerción. La incompletitud parcial de NPK
// queda como backlog, porque avisarla en cada lectura sería fatiga de alertas (B.7).
//
// Esta guarda va ANTES que la de lectura sospechosa por una razón concreta: cuando dos
// guardas compiten, se reporta la de condición PERMANENTE. Un sensor desconectado se
// vuelve a anunciar en la lectura siguiente; un hueco de configuración enmascarado no
// se anuncia nunca.
// ============================================================
const tieneUmbrales = !!reglas
  && reglas.humedad_min != null && reglas.humedad_max != null
  && reglas.ph_min      != null && reglas.ph_max      != null;

if (!tieneUmbrales) {
  return [{
    json: {
      cultivo_id: cultivo.cultivo_id,
      dispositivo_id: cultivo.dispositivo_id,
      planta: cultivo.planta,
      etapa: cultivo.etapa_actual,
      mac_address: sensor.dispositivo_mac,
      humedad: sensor.humedad, ph: sensor.ph, n: sensor.n, p: sensor.p, k: sensor.k,
      estado: 'Sin Umbrales - Configuracion Incompleta',
      observaciones: [
        `⚙️ CONFIGURACIÓN INCOMPLETA: no hay umbrales agronómicos cargados para ` +
        `${cultivo.planta} en etapa "${cultivo.etapa_actual}". El sistema NO puede evaluar ` +
        `esta lectura, y no la está evaluando: no la está aprobando. Hasta que se carguen ` +
        `los parámetros de esta etapa, este cultivo queda sin diagnóstico automático y sin ` +
        `riego automático.`
      ],
      detalle_metricas: [],
      total_alertas: 1,

      // Contrato uniforme (13.3.3): mismos campos y mismos TIPOS que las otras dos salidas.
      lectura_sospechosa: false,
      hay_sequia: false,
      hay_estres_quimico: false,
      hay_exceso_hidrico: false,
      falla_riego_persistente: false,
      en_mantenimiento: enMantenimiento,
      volumen_maceta_litros: cultivo.volumen_maceta_litros,
      caudal_bomba_ml_s: cultivo.caudal_bomba_ml_s,
      tiene_actuador_riego: cultivo.tiene_actuador_riego, // ya normalizado en el borde (16.35)
      tiene_foto: fotoPlausible,
      // 13.7.2 — contrato uniforme: el consumidor lo lee en todos los caminos. Acá no se evaluó.
      recheck_riego: null,

      // 16.36 — sin este `true` la alerta NO se dispara: `Requiere Alerta?` dejó de
      // rutear sobre `estado !== 'OK'`. Es el punto exacto donde 16.37 y 16.36, cada
      // uno correcto por separado, se rompían en composición.
      requiere_alerta: true,

      // Se emiten vacíos y no ausentes: el consumidor espera el objeto, y un `undefined`
      // acá reintroduciría la misma clase de fallo que esta guarda viene a evitar.
      umbrales: {
        humedad: { min: null, max: null },
        ph: { min: null, max: null },
        n_ideal: null, p_ideal: null, k_ideal: null
      },

      timestamp: new Date().toISOString()
    }
  }];
}

// --- Chequeo de plausibilidad: sensor posiblemente desconectado (ver 13.3.1) ---
// Dos formas de "no hay con qué decidir", las dos con alerta y sin acción automática:
//   · todos en 0:    el sensor probablemente está desconectado (13.3.1);
//   · todos en null: la placa DECLARA que no pudo medir nada (contrato v1, regla 1).
// Sin la segunda, una lectura sin ningún dato no evaluaba nada y salía 'OK'.
const valoresCriticos = [sensor.humedad, sensor.ph, sensor.n, sensor.p, sensor.k];
const todosEnCero  = valoresCriticos.every(v => v === 0);
const todosSinDato = valoresCriticos.every(v => v === null);
const lecturaSospechosa = todosEnCero || todosSinDato;

if (lecturaSospechosa) {
  return [{
    json: {
      cultivo_id: cultivo.cultivo_id,
      dispositivo_id: cultivo.dispositivo_id,
      planta: cultivo.planta,
      etapa: cultivo.etapa_actual,
      mac_address: sensor.dispositivo_mac,
      humedad: sensor.humedad, ph: sensor.ph, n: sensor.n, p: sensor.p, k: sensor.k,
      estado: todosSinDato ? 'Lectura Sin Datos - Revisar Sensor' : 'Lectura Sospechosa - Revisar Sensor',
      observaciones: [
        todosSinDato
          ? `⚠️ LECTURA SIN DATOS: la placa informó que no pudo medir humedad, pH, N, P ni K. ` +
            `Revisar el sensor y su conexión con la placa. No se disparó ninguna acción automática.`
          : `⚠️ LECTURA SOSPECHOSA: humedad, pH, N, P y K llegaron todos en 0 al mismo tiempo — prácticamente imposible con un sensor funcionando normal. ` +
            `Probablemente está desconectado o mal insertado en el sustrato (frecuente después de un trasplante). No se disparó ninguna acción automática con este dato.`
      ],
      detalle_metricas: [],
      total_alertas: 1,
      lectura_sospechosa: true,

      // Contrato uniforme (13.3.3) — los IF de 13.4 leen estos campos con typeValidation strict.
      // Valores neutros: acá no se evaluó nada. El discriminador de ese caso es lectura_sospechosa.
      hay_sequia: false,
      hay_estres_quimico: false,
      falla_riego_persistente: false,
      en_mantenimiento: enMantenimiento,
      volumen_maceta_litros: cultivo.volumen_maceta_litros,
      caudal_bomba_ml_s: cultivo.caudal_bomba_ml_s,
      tiene_actuador_riego: cultivo.tiene_actuador_riego, // ya normalizado en el borde (16.35)
      tiene_foto: fotoPlausible,
      // 13.7.2 — contrato uniforme: el consumidor lo lee en todos los caminos. Acá no se evaluó.
      recheck_riego: null,
      hay_exceso_hidrico: false,
      // 16.36 — hecho de dominio: una lectura sospechosa siempre se notifica.
      requiere_alerta: true,
      umbrales: {
        humedad: { min: reglas.humedad_min, max: reglas.humedad_max },
        ph: { min: reglas.ph_min, max: reglas.ph_max },
        n_ideal: reglas.ideal_n, p_ideal: reglas.ideal_p, k_ideal: reglas.ideal_k
      },

      timestamp: new Date().toISOString()
    }
  }];
}

// 2. MOTOR DE REGLAS (INFERENCIA)
let estadoGlobal = 'OK';
const observaciones = [];
const detalleMetricas = [];

// Hechos de dominio (13.4.2): se marcan donde la condición se detecta, no se derivan
// después parseando el texto de las observaciones — ese texto es presentación, no dato.
let haySequiaFlag = false;
let hayEstresQuimicoFlag = false;
// 16.36 — el exceso hídrico no tenía hecho de dominio: cambiaba `estadoGlobal` y
// nada más. Sin este flag, cualquier condición armada sobre los booleanos lo
// perdería, y hoy es la única vía por la que un estado != 'OK' no tiene bandera.
let hayExcesoHidricoFlag = false;

// Tolerancia para NPK (±30% del valor ideal)
const NPK_TOLERANCIA = 0.30;
// --- EVALUAR HUMEDAD (tiene min/max directos) ---
if (sensor.humedad !== undefined && sensor.humedad !== null) {
  let estadoH = 'OK';
  if (sensor.humedad < reglas.humedad_min) {
    estadoH = 'BAJO';
    estadoGlobal = 'Sequía';
    haySequiaFlag = true;
    observaciones.push(
      `🔴 SEQUÍA: Humedad del suelo = ${sensor.humedad}% está por debajo del mínimo (${reglas.humedad_min}%). ` +
      `Déficit de ${(reglas.humedad_min - sensor.humedad).toFixed(1)}%.`
    );
  } else if (sensor.humedad > reglas.humedad_max) {
    estadoH = 'ALTO';
    hayExcesoHidricoFlag = true;
    if (estadoGlobal === 'OK') estadoGlobal = 'Exceso Hídrico';
    observaciones.push(
      `🟠 EXCESO HÍDRICO: Humedad = ${sensor.humedad}% supera el máximo (${reglas.humedad_max}%). ` +
      `Excedente de ${(sensor.humedad - reglas.humedad_max).toFixed(1)}%.`
    );
  }
  detalleMetricas.push({
    metrica: 'Humedad Suelo',
    valor: sensor.humedad,
    rango: `${reglas.humedad_min}% - ${reglas.humedad_max}%`,
    estado: estadoH
  });
}
// --- EVALUAR pH (tiene min/max directos) ---
if (sensor.ph !== undefined && sensor.ph !== null) {
  let estadoPH = 'OK';
  if (sensor.ph < reglas.ph_min) {
    estadoPH = 'BAJO';
    hayEstresQuimicoFlag = true;
    if (estadoGlobal === 'OK') estadoGlobal = 'Estrés Químico';
    observaciones.push(
      `🟡 pH ÁCIDO: pH = ${sensor.ph} está por debajo del mínimo (${reglas.ph_min}). ` +
      `Riesgo de bloqueo de nutrientes. Déficit de ${(reglas.ph_min - sensor.ph).toFixed(2)} unidades.`
    );
  } else if (sensor.ph > reglas.ph_max) {
    estadoPH = 'ALTO';
    hayEstresQuimicoFlag = true;
    if (estadoGlobal === 'OK') estadoGlobal = 'Estrés Químico';
    observaciones.push(
      `🟡 pH ALCALINO: pH = ${sensor.ph} supera el máximo (${reglas.ph_max}). ` +
      `Riesgo de bloqueo de micronutrientes. Exceso de ${(sensor.ph - reglas.ph_max).toFixed(2)} unidades.`
    );
  }
  detalleMetricas.push({
    metrica: 'pH',
    valor: sensor.ph,
    rango: `${reglas.ph_min} - ${reglas.ph_max}`,
    estado: estadoPH
  });
}
// --- EVALUAR NPK (usa valor ideal ± tolerancia) ---
const npkChecks = [
  { campo: 'n', ideal: reglas.ideal_n, nombre: 'Nitrógeno (N)' },
  { campo: 'p', ideal: reglas.ideal_p, nombre: 'Fósforo (P)' },
  { campo: 'k', ideal: reglas.ideal_k, nombre: 'Potasio (K)' }
];
for (const check of npkChecks) {
  const valor = sensor[check.campo];
  if (valor === undefined || valor === null || check.ideal === null) continue;

  const minNPK = check.ideal * (1 - NPK_TOLERANCIA);
  const maxNPK = check.ideal * (1 + NPK_TOLERANCIA);
  let estadoNPK = 'OK';

  if (valor < minNPK) {
    estadoNPK = 'BAJO';
    hayEstresQuimicoFlag = true;
    if (estadoGlobal === 'OK') estadoGlobal = 'Estrés Químico';
    observaciones.push(
      `🟡 DÉFICIT ${check.nombre}: ${valor} mg/kg por debajo del rango tolerable (${minNPK.toFixed(0)} - ${maxNPK.toFixed(0)} mg/kg). ` +
      `Ideal: ${check.ideal} mg/kg.`
    );
  } else if (valor > maxNPK) {
    estadoNPK = 'ALTO';
    hayEstresQuimicoFlag = true;
    if (estadoGlobal === 'OK') estadoGlobal = 'Estrés Químico';
    observaciones.push(
      `🟠 EXCESO ${check.nombre}: ${valor} mg/kg supera el rango tolerable (${minNPK.toFixed(0)} - ${maxNPK.toFixed(0)} mg/kg). ` +
      `Ideal: ${check.ideal} mg/kg.`
    );
  }
  detalleMetricas.push({
    metrica: check.nombre,
    valor: valor,
    rango: `${minNPK.toFixed(0)} - ${maxNPK.toFixed(0)} mg/kg (ideal: ${check.ideal})`,
    estado: estadoNPK
  });
}
// 3. CLASIFICACIÓN COMPUESTA (13.4.2: sobre los flags, ya no parseando observaciones)
if (haySequiaFlag && hayEstresQuimicoFlag) {
  estadoGlobal = 'Sequía + Estrés Químico';
}

// ============================================================
// 13.7.2 — RECHECK DEL ÚLTIMO RIEGO Y FRENO (circuit breaker)
// ------------------------------------------------------------
// El recheck se evalúa ACÁ, con ESTA lectura, y ANTES de decidir si se riega.
// El diseño de 13.7.1 lo cerraba en un nodo posterior: en la lectura del
// recheck el Motor todavía veía el riego `pendiente`, no frenaba, y WF5
// ordenaba otro riego. En la lectura siguiente el "último riego" era el nuevo,
// otra vez `pendiente`. Con lecturas cada 15 min o más, el freno nunca miraba
// un riego cerrado. Acá se infiere; `Registrar Recheck de Riego` solo guarda.
//
// Tres resultados. El freno detecta que el riego NO TUVO EFECTO, no que la
// dosis no alcanzó: con el pulso topeado a 30 s una dosis corta es esperable,
// y la cantidad de reintentos la acota el tope duro de fn_registrar_riego (16.46).
//   exitoso       → la humedad volvió al rango (>= mínimo de la etapa).
//   insuficiente  → subió al menos DELTA_MIN_EFECTO pero sigue baja: puede volver a regar.
//   fallo_sistema → no subió: freno, alerta, y decide un humano.
// Los TIEMPOS (absorción 15 min, vencimiento 60 min) no se definen acá: vienen
// de `vista_ultimo_riego`, que es la misma definición que usa el cooldown de WF5.
// ============================================================
const DELTA_MIN_EFECTO = 3; // puntos de humedad. Sin procedencia todavía: sale del piloto (B3)

// La ausencia se decide ANTES de convertir: Number(null) === 0 y Number('') === 0.
const numOrNull = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

// Requiere "Always Output Data" en `Obtener Ultimo Riego` (13.3.3): sin riegos llega `{}`.
let ultimoRiego = null;
try {
  ultimoRiego = $('Obtener Ultimo Riego').first()?.json ?? null;
} catch (e) {
  ultimoRiego = null; // el nodo no corrió en esta ejecución
}
if (ultimoRiego && ultimoRiego.fecha_inicio == null) ultimoRiego = null; // `{}` = no hay riegos
// Validación positiva: si hay un riego, la vista tiene que traer las columnas del
// recheck. Sin ellas el freno quedaría ciego y todas las ejecuciones en verde.
if (ultimoRiego && (ultimoRiego.evento_id == null
    || typeof ultimoRiego.absorcion_completa !== 'boolean'
    || typeof ultimoRiego.recheck_vencido !== 'boolean')) {
  throw new Error('vista_ultimo_riego no trae evento_id / absorcion_completa / recheck_vencido: ' +
    'falta aplicar SQL/sesion16_lazo_riego.sql. Sin esas columnas el freno de riego no funciona.');
}

const humedadLectura = numOrNull(sensor.humedad);

// --- ¿Esta lectura es el recheck del último riego? ---
let recheckRiego = null;
if (!enMantenimiento && ultimoRiego && ultimoRiego.resultado === 'pendiente'
    && ultimoRiego.absorcion_completa === true && ultimoRiego.recheck_vencido === false
    && humedadLectura !== null) {
  const humedadInicial = numOrNull(ultimoRiego.humedad_inicial);
  let resultado;
  if (humedadLectura >= reglas.humedad_min) {
    resultado = 'exitoso';
  } else if (humedadInicial !== null && humedadLectura - humedadInicial >= DELTA_MIN_EFECTO) {
    resultado = 'insuficiente';
  } else {
    // No subió, o no hay con qué medirlo: ante la duda, el estado seguro es no regar.
    resultado = 'fallo_sistema';
  }
  recheckRiego = {
    evento_id:       ultimoRiego.evento_id,
    humedad:         humedadLectura,
    humedad_inicial: humedadInicial,
    resultado:       resultado
  };
  if (resultado === 'insuficiente') {
    observaciones.push(
      `💧 El riego anterior subió la humedad de ${humedadInicial}% a ${humedadLectura}%, sin llegar al ` +
      `mínimo (${reglas.humedad_min}%). Puede volver a regar, dentro del tope de seguridad.`
    );
  }
}

// --- Freno: el último riego no tuvo efecto ---
// Si el recheck es de esta lectura, manda ese resultado; si no, el que quedó guardado.
const resultadoVigente = recheckRiego ? recheckRiego.resultado : (ultimoRiego ? ultimoRiego.resultado : null);

// Rearme por evidencia: después del recheck fallido se volvió a ver la maceta
// húmeda, o sea que alguien la atendió. Si el recheck es de esta lectura, no hay
// "después" todavía.
const humedadPosterior = recheckRiego ? null : numOrNull(ultimoRiego?.humedad_max_posterior);
const rearmado = humedadPosterior !== null && humedadPosterior >= reglas.humedad_min;

let fallaRiegoPersistente = false;
if (!enMantenimiento && haySequiaFlag && resultadoVigente === 'fallo_sistema' && !rearmado) {
  fallaRiegoPersistente = true;
  estadoGlobal = 'Falla de Riego - Revisar Sistema';

  const hIni = recheckRiego ? recheckRiego.humedad_inicial : numOrNull(ultimoRiego.humedad_inicial);
  const hRec = recheckRiego ? recheckRiego.humedad : numOrNull(ultimoRiego.humedad_recheck);
  // 16.63 (mitad): el estado de la orden distingue conectividad de bomba/tanque.
  const estadoOrden = ultimoRiego.comando_estado ?? 'desconocido';
  let causa;
  if (estadoOrden === 'pendiente' || estadoOrden === 'entregado') {
    causa = `La orden figura "${estadoOrden}": el dispositivo no confirmó haberla ejecutado. ` +
            `Revisar primero la conexión de la placa.`;
  } else if (estadoOrden === 'ejecutado') {
    causa = `La orden se ejecutó y la humedad no subió. Revisar: ¿hay agua en el tanque?, ` +
            `¿la bomba funciona?, ¿hay una fuga?, ¿el sensor quedó bien enterrado?`;
  } else {
    causa = `Estado de la orden: "${estadoOrden}". Revisar la placa, el tanque, la bomba y el sensor.`;
  }
  observaciones.push(
    `🆘 FALLA DE RIEGO: se regó con humedad ${hIni ?? '?'}% y en el control seguía en ${hRec ?? '?'}%. ` +
    `${causa} El riego automático queda suspendido hasta que se vea la maceta húmeda de nuevo.`
  );
}

// 4. SALIDA UNIFICADA
return [{
  json: {
    // Identidad del cultivo
    cultivo_id:       cultivo.cultivo_id,
    dispositivo_id:   cultivo.dispositivo_id,
    planta:           cultivo.planta,
    etapa:            cultivo.etapa_actual,
    mac_address:      sensor.dispositivo_mac,
    etapas_especie_id: cultivo.etapas_especie_id,
    foto_base64:      fotoBase64,

    // Valores crudos del sensor
    humedad:  sensor.humedad,
    ph:       sensor.ph,
    n:        sensor.n,
    p:        sensor.p,
    k:        sensor.k,

    // Diagnóstico del sistema experto (texto = presentación, para humanos)
    estado:           estadoGlobal,
    observaciones:    observaciones,
    detalle_metricas: detalleMetricas,
    total_alertas:    observaciones.length,

    // Hechos de dominio (13.4.2) — sobre estos rutean los IF de 13.4, nunca sobre `estado`
    hay_sequia:              haySequiaFlag,
    hay_estres_quimico:      hayEstresQuimicoFlag,
    hay_exceso_hidrico:      hayExcesoHidricoFlag,
    falla_riego_persistente: fallaRiegoPersistente,
    en_mantenimiento:        enMantenimiento,
    lectura_sospechosa:      false,

    // 16.36 — LA DEFINICIÓN VIVE EN EL PRODUCTOR.
    // `Requiere Alerta?` ruteaba sobre `estado !== 'OK'`, o sea sobre el string de
    // presentación. Este booleano es el mismo predicado expresado sobre hechos de
    // dominio, y es equivalente por construcción: `estadoGlobal` sale de 'OK'
    // exactamente cuando alguna de estas cuatro banderas se enciende.
    requiere_alerta: haySequiaFlag || hayEstresQuimicoFlag || hayExcesoHidricoFlag || fallaRiegoPersistente,

    // Umbrales usados (para trazabilidad)
    umbrales: {
      humedad: { min: reglas.humedad_min, max: reglas.humedad_max },
      ph: { min: reglas.ph_min, max: reglas.ph_max },
      n_ideal: reglas.ideal_n,
      p_ideal: reglas.ideal_p,
      k_ideal: reglas.ideal_k
    },

    // Fase 13: riego automático
    volumen_maceta_litros: cultivo.volumen_maceta_litros,
    caudal_bomba_ml_s:     cultivo.caudal_bomba_ml_s,
    tiene_actuador_riego:  cultivo.tiene_actuador_riego, // ya normalizado en el borde (16.35)
    tiene_foto: fotoPlausible,

    // 13.7.2 — conclusión del recheck de esta lectura (null si esta lectura no es un recheck).
    // La guarda `Registrar Recheck de Riego`.
    recheck_riego: recheckRiego,

    timestamp: new Date().toISOString()
  }
}];

